{{pins}}
#include <SPI.h>
#include <MFRC522.h>

MFRC522 reader(RFID_SS, RFID_RST);

// The card's ID as text, like DEADBEEF.
String cardId() {
  String id = "";
  for (byte i = 0; i < reader.uid.size; i++) {
    if (reader.uid.uidByte[i] < 0x10) id += "0";
    id += String(reader.uid.uidByte[i], HEX);
  }
  id.toUpperCase();
  return id;
}

void setup() {
  Serial.begin(9600);
  SPI.begin();
  reader.PCD_Init();
  Serial.println("Hold a card on the reader...");
}

void loop() {
  if (reader.PICC_IsNewCardPresent() && reader.PICC_ReadCardSerial()) {
    Serial.print("Card: ");
    Serial.println(cardId());
    reader.PICC_HaltA();
  }
}

