#include <Servo.h>
#include <SPI.h>
#include <MFRC522.h>

MFRC522 reader(RFID_SS, RFID_RST);

const int CARDS = 3;
const String ALLOWED[CARDS] = { "DEADBEEF", "12345678", "CAFEF00D" };
int visits = 0;
Servo latch;

// The card's ID as text, like DEADBEEF.
String cardId() {
  String id = "";
  for (byte i = 0; i < reader.uid.size; i++) {
    if (reader.uid.uidByte[i] < 0x10) id += "0";
    id += String(reader.uid.uidByte[i], HEX);
  }
  id.toUpperCase();
  return id;
}

void setup() {
  Serial.begin(9600);
  SPI.begin();
  reader.PCD_Init();
  pinMode(LED_GREEN, OUTPUT);
  pinMode(LED_RED, OUTPUT);
  latch.attach(SERVO_PIN);
  latch.write(0);
}

void loop() {
  if (!reader.PICC_IsNewCardPresent() || !reader.PICC_ReadCardSerial()) return;
  String id = cardId();
  reader.PICC_HaltA();
  bool ok = false;
  for (int i = 0; i < CARDS; i++) {
    if (id == ALLOWED[i]) ok = true;
  }
  visits++;
  Serial.print("#");
  Serial.print(visits);
  Serial.print(" card ");
  Serial.print(id);
  Serial.print(": ");
  if (ok) {
    Serial.println("Welcome!");
    digitalWrite(LED_GREEN, HIGH);
    latch.write(90);    // open
    delay(3000);
    latch.write(0);     // close again
    digitalWrite(LED_GREEN, LOW);
  } else {
    Serial.println("Access denied");
    digitalWrite(LED_RED, HIGH);
    delay(1000);
    digitalWrite(LED_RED, LOW);
  }
}
